<script setup lang="ts">
import {computed,onMounted,reactive,ref} from 'vue';
import ImageCropDialog from './ImageCropDialog.vue';
import SitePublish from './SitePublish.vue';
import {adminMediaUrl,getVisitorState,postVisitor,visitorHomeUrl,type VContent,type VPayload} from './visitor-content-api';

type Section='home'|'themes'|'unassigned'|'places'|'route';
type Slot={slot:string;title:string;subtitle:string;aspect:number;placeCode?:string;contentId?:string;familyFriendly?:boolean};
const payload=ref<VPayload|null>(null),message=ref(''),busy=ref(false),section=ref<Section>('home'),activeTheme=ref('water'),query=ref(''),addQuery=ref(''),showAdd=ref(false),showCreate=ref(false),showAuxiliary=ref(false),crop=ref<{file:File;item:Slot}|null>(null),cropQueue=ref<Array<{file:File;item:Slot}>>([]);
const cardEdits=reactive<Record<string,{title:string;summary:string}>>({});
const contentEdits=reactive<Record<string,{title:string;summary:string}>>({});
const moveTargets=reactive<Record<string,string>>({});
const expandedFacilities=reactive<Record<string,boolean>>({});
const newCard=reactive({title:'',summary:'',placeCode:'',themeIds:[] as string[],familyFriendly:false,kind:'outdoor'});
const homeDefaults={eyebrow:'一位本地爸爸的沿路笔记',titleLine1:'武夷山',titleLine2:'奶爸地图',introLine1:'我在武夷山生活，',introLine2:'把自己实际走过、愿意推荐的地方放在这里。',mapButtonLabel:'看地图',corridorButtonLabel:'一号风景道',kidsLabel:'适合带孩子',themeCardHint:'看看怎么安排',recommendationsEyebrow:'沿路挑三处',recommendationsTitle:'最近推荐',recommendationsLinkLabel:'查看路线 →',recommendationManshuiTitle:'漫水桥',recommendationManshuiSummary:'河边停一停，先看当天水况',recommendationMoonbayTitle:'月亮湾',recommendationMoonbaySummary:'在整条路线地图中查看位置',recommendationTaoyuanyuTitle:'桃源峪',recommendationTaoyuanyuSummary:'先在自然里找，再去展馆看懂',routesEyebrow:'按时间和同行人安排',routesTitle:'推荐路线',routeFamilyTitle:'带娃怎么玩',routeFamilySummary:'带孩子轻松走，优先选择方便停留的地方',routeDayTitle:'一天怎么玩',routeDaySummary:'用一天串起山水、茶和沿路停留',routeTwoDayTitle:'两天怎么玩',routeTwoDaySummary:'第一天看山水，第二天慢慢走进茶与自然'};
const homeText=reactive({...homeDefaults});
type HomeTextKey=keyof typeof homeText;
const themeEdits=reactive<Record<string,{name:string;icon:string;eyebrow:string;description:string}>>({});
const validPlaces=computed(()=>payload.value?.places.filter(place=>!place.deleted_at&&!place.duplicate_of_place_id)||[]);
const contents=computed(()=>payload.value?.state.contents.filter(item=>!item.deletedAt)||[]);
const themes=computed(()=>payload.value?.state.themes||[]);
const media=computed(()=>payload.value?.state.media);
const activeThemeData=computed(()=>themes.value.find(theme=>theme.id===activeTheme.value));

async function load(){payload.value=await getVisitorState();activeTheme.value=payload.value.state.themes.some(theme=>theme.id===activeTheme.value)?activeTheme.value:(payload.value.state.themes[0]?.id||'water');Object.assign(homeText,homeDefaults,payload.value.state.home.published);for(const theme of payload.value.state.themes)themeEdits[theme.id]={name:theme.name,icon:theme.icon,eyebrow:theme.eyebrow,description:theme.description};}
onMounted(async()=>{try{await load();}catch(error){message.value=(error as Error).message;}});
function image(slot:string){return adminMediaUrl(media.value?.items[slot]||(slot==='home.hero'?payload.value?.state.home.published.heroImage:null));}
function gallery(slot:string){if(!media.value)return [] as Array<{slot:string;url:string}>;return Object.entries(media.value.items).filter(([key])=>key===slot||key.startsWith(slot+'.gallery.')).sort((a,b)=>a[1].uploadedAt.localeCompare(b[1].uploadedAt)).map(([key,value])=>({slot:key,url:adminMediaUrl(value)}));}
function supportsGallery(item:Slot){return /^(place|content)\./.test(item.slot)&&item.slot.endsWith('.cover');}
function placeName(code:string){return validPlaces.value.find(place=>place.code===code)?.name||code;}
function assignment(code:string){return payload.value?.state.placeAssignments.find(item=>item.placeCode===code);}
type FacilityKey='toilet'|'shop'|'restaurant'|'lodging';
const facilityOptions:Array<[FacilityKey,string]>=[['toilet','卫生间'],['shop','商店'],['restaurant','餐馆'],['lodging','住宿']];
function facilityState(code:string){return {...{toilet:code==='WY-0004',shop:false,restaurant:false,lodging:false},...(assignment(code)?.facilities||{})};}
function itemPlaceCode(item:Slot){if(item.placeCode)return item.placeCode;const content=contents.value.find(row=>row.id===item.contentId);return content?.draft.navigationTargets.find(target=>target.isDefault)?.placeCode||content?.draft.placeLinks[0]?.placeCode||'';}
function cardEditForTheme(code:string,themeId:string){const key=`${themeId}:${code}`,current=assignment(code);return cardEdits[key]??(cardEdits[key]={title:current?.titleByTheme[themeId]||placeName(code),summary:current?.summaryByTheme[themeId]||''});}
function cardEdit(code:string){return cardEditForTheme(code,activeTheme.value);}
function contentEdit(id:string){const content=contents.value.find(item=>item.id===id);return contentEdits[id]??(contentEdits[id]={title:content?.draft.title||'',summary:content?.draft.summary||''});}
function setCardText(item:Slot,field:'title'|'summary',event:Event){const value=((event.currentTarget as HTMLElement).innerText||'').trim();if(item.placeCode)cardEdit(item.placeCode)[field]=value;else if(item.contentId)contentEdit(item.contentId)[field]=value;}
function setPlaceThemeText(code:string,themeId:string,field:'title'|'summary',event:Event){cardEditForTheme(code,themeId)[field]=((event.currentTarget as HTMLElement).innerText||'').trim();}
function contentBySlug(slug:string){return contents.value.find(item=>item.draft.slug===slug);}
function contentSlot(content:VContent|undefined,suffix='cover'){return content?`content.${content.id}.${suffix}`:'';}
function placeSlot(code:string){return `place.${code}.cover`;}
const homeSlots=computed<Slot[]>(()=>[
 {slot:'home.hero',title:'首页主图',subtitle:'游客打开首页首先看到的图片',aspect:.8},
 {slot:contentSlot(contentBySlug('manshui'))||placeSlot('WY-0009'),title:homeText.recommendationManshuiTitle,subtitle:homeText.recommendationManshuiSummary,aspect:1.45},
 {slot:placeSlot('WY-0012'),title:homeText.recommendationMoonbayTitle,subtitle:homeText.recommendationMoonbaySummary,aspect:1.45},
 {slot:placeSlot('WY-0024'),title:homeText.recommendationTaoyuanyuTitle,subtitle:homeText.recommendationTaoyuanyuSummary,aspect:1.45}
]);
const themeSlots=computed<Slot[]>(()=>{
 const theme=activeThemeData.value;if(!theme||!payload.value)return [];
 const represented=new Set<string>(),items:Slot[]=[{slot:`theme.${theme.id}.hero`,title:`${theme.name}主题头图`,subtitle:'主题页顶部图片',aspect:1.45}];
 const rawAssignments=payload.value.state.placeAssignments.filter(item=>item.themeIds.includes(theme.id)).sort((a,b)=>(a.orderByTheme[theme.id]??99999)-(b.orderByTheme[theme.id]??99999));
 const assignments=rawAssignments;
 for(const item of assignments){represented.add(item.placeCode);items.push({slot:placeSlot(item.placeCode),title:item.titleByTheme[theme.id]||placeName(item.placeCode),subtitle:item.summaryByTheme[theme.id]||`${item.placeCode} · 地点卡片`,aspect:1.45,placeCode:item.placeCode,familyFriendly:item.familyFriendly});}
 for(const content of contents.value.filter(item=>item.draft.themeIds.includes(theme.id)&&(item.draft.slug.startsWith('card-')||!item.draft.placeLinks.some(link=>represented.has(link.placeCode)))))items.push({slot:contentSlot(content),title:content.draft.title,subtitle:content.draft.summary||'内容卡片',aspect:1.45,contentId:content.id,familyFriendly:content.draft.familyFriendly});
 return [...new Map(items.map(item=>[item.slot,item])).values()];
});
const placeSlots=computed<Slot[]>(()=>validPlaces.value.filter(place=>!query.value||`${place.name}${place.code}${place.old_names.join('')}`.toLowerCase().includes(query.value.toLowerCase())).map(place=>({slot:placeSlot(place.code),title:place.name,subtitle:`${place.code} · 地点图片`,aspect:1.45,placeCode:place.code,familyFriendly:assignment(place.code)?.familyFriendly||false})));
const routeSlots:Slot[]=[{slot:'corridor.hero',title:'一号风景道主图',subtitle:'路线页顶部图片',aspect:1.45}];
const unassignedSlots=computed<Slot[]>(()=>{
 if(!payload.value)return [];
 const assigned=new Map(payload.value.state.placeAssignments.map(item=>[item.placeCode,item]));
 const placeItems=validPlaces.value.filter(place=>(showAuxiliary.value||place.place_type==='主地点')&&!(assigned.get(place.code)?.themeIds.length)).map(place=>({slot:placeSlot(place.code),title:place.name,subtitle:`${place.code} · 尚未加入主题`,aspect:1.45,placeCode:place.code,familyFriendly:assigned.get(place.code)?.familyFriendly||false}));
 const contentItems=contents.value.filter(item=>!item.draft.themeIds.length).map(content=>({slot:contentSlot(content),title:content.draft.title,subtitle:content.draft.summary||'尚未加入主题',aspect:1.45,contentId:content.id,familyFriendly:content.draft.familyFriendly}));
 const needle=query.value.trim().toLowerCase();
 return [...placeItems,...contentItems].filter(item=>!needle||`${item.title}${item.subtitle}`.toLowerCase().includes(needle));
});
const visibleSlots=computed(()=>section.value==='home'?[]:section.value==='themes'?themeSlots.value.slice(1):section.value==='unassigned'?unassignedSlots.value:section.value==='places'?placeSlots.value:routeSlots);
const availablePlaces=computed(()=>{
 const selected=new Set(payload.value?.state.placeAssignments.filter(item=>item.themeIds.includes(activeTheme.value)).map(item=>item.placeCode)||[]),needle=addQuery.value.trim().toLowerCase();
 return validPlaces.value.filter(place=>!selected.has(place.code)&&(showAuxiliary.value||place.place_type==='主地点')&&(!needle||`${place.name}${place.code}${place.old_names.join('')}`.toLowerCase().includes(needle))).slice(0,30);
});
const availableContents=computed(()=>contents.value.filter(item=>!item.draft.themeIds.includes(activeTheme.value)).slice(0,20));

function choose(event:Event,item:Slot){const input=event.target as HTMLInputElement,file=input.files?.[0];input.value='';if(file)crop.value={file,item};}
function chooseGallery(event:Event,item:Slot){const input=event.target as HTMLInputElement,files=Array.from(input.files||[]);input.value='';if(!files.length)return;const existing=gallery(item.slot).length;const stamp=Date.now();const jobs=files.map((file,index)=>({file,item:{...item,slot:existing||index?`${item.slot}.gallery.${stamp}-${index}`:item.slot}}));crop.value=jobs.shift()||null;cropQueue.value=jobs;}
async function applyCrop(blob:Blob){
 if(!crop.value||!payload.value)return;const item=crop.value.item;busy.value=true;message.value='正在更新图片…';
 try{const response=await fetch(`/api/admin/visitor-content/visual-media/${encodeURIComponent(item.slot)}`,{method:'POST',headers:{'Content-Type':'image/jpeg','X-Media-Version':String(payload.value.state.media.version),'X-Original-Name':encodeURIComponent(crop.value.file.name)},body:blob});const body=await response.json();if(!response.ok)throw new Error(body.error||'图片更新失败');payload.value.state.media=body.media;crop.value=cropQueue.value.shift()||null;message.value=crop.value?'这张已加入，请继续调整下一张照片。':`“${item.title}”图片已更新。`;}
 catch(error){message.value=(error as Error).message;}finally{busy.value=false;}
}
async function removeImage(item:Slot){if(!payload.value||!confirm(`确认移除“${item.title}”的图片？`))return;busy.value=true;try{const result=await postVisitor<any>(`/visual-media/${encodeURIComponent(item.slot)}/remove`,{expected_version:payload.value.state.media.version});payload.value.state.media=result.media;message.value=`“${item.title}”图片已移除。`;}catch(error){message.value=(error as Error).message;}finally{busy.value=false;}}
async function removeGalleryImage(item:Slot,slot:string){return removeImage({...item,slot});}
async function savePlacePresentation(code:string,themeIds:string[],familyFriendly:boolean,facilities?:{toilet:boolean;shop:boolean;restaurant:boolean;lodging:boolean}){
 if(!payload.value)return;const current=assignment(code);busy.value=true;
 try{await postVisitor('/place-themes',{place_code:code,expected_version:current?.version||0,theme_ids:themeIds,family_friendly:familyFriendly,title_by_theme:current?.titleByTheme||{},summary_by_theme:current?.summaryByTheme||{},...(facilities?{facilities}:{})});await load();}
 catch(error){message.value=(error as Error).message;throw error;}finally{busy.value=false;}
}
async function addPlace(code:string){const current=assignment(code);try{await savePlacePresentation(code,[...new Set([...(current?.themeIds||[]),activeTheme.value])],current?.familyFriendly||false);message.value=`已把“${placeName(code)}”加入${activeThemeData.value?.name||''}。`;}catch{}}
async function addPlaceToTheme(code:string,themeId:string){const current=assignment(code),theme=themes.value.find(item=>item.id===themeId);try{await savePlacePresentation(code,[...new Set([...(current?.themeIds||[]),themeId])],current?.familyFriendly||false);message.value=`已把“${placeName(code)}”加入${theme?.name||themeId}。`;}catch{}}
async function togglePlaceTheme(code:string,themeId:string){const current=assignment(code),has=current?.themeIds.includes(themeId)||false,themeIds=has?(current?.themeIds||[]).filter(id=>id!==themeId):[...new Set([...(current?.themeIds||[]),themeId])];try{await savePlacePresentation(code,themeIds,current?.familyFriendly||false);message.value=`“${placeName(code)}”已${has?'移出':'加入'}${themes.value.find(theme=>theme.id===themeId)?.name||themeId}。`;}catch{}}
async function removePlace(code:string){const current=assignment(code);if(!current)return;try{await savePlacePresentation(code,current.themeIds.filter(id=>id!==activeTheme.value),current.familyFriendly);message.value=`已从${activeThemeData.value?.name||''}移除“${placeName(code)}”。`;}catch{}}
async function movePlace(code:string){const target=moveTargets[`place:${code}`],current=assignment(code);if(!target||!current)return;const theme=themes.value.find(item=>item.id===target);try{await savePlacePresentation(code,[...new Set([...current.themeIds.filter(id=>id!==activeTheme.value),target])],current.familyFriendly);message.value=`已把“${placeName(code)}”移动至${theme?.name||target}。`;}catch{}}
async function togglePlaceFamily(code:string){const current=assignment(code);try{await savePlacePresentation(code,current?.themeIds||[],!current?.familyFriendly);message.value=`“${placeName(code)}”已${current?.familyFriendly?'取消':'设为'}适合带孩子。`;}catch{}}
async function setFacility(code:string,key:FacilityKey,value:boolean){const current=assignment(code),next={...facilityState(code),[key]:value};try{await savePlacePresentation(code,current?.themeIds||[],current?.familyFriendly||false,next);const label={toilet:'卫生间',shop:'商店',restaurant:'餐馆',lodging:'住宿'}[key];message.value=`“${placeName(code)}”的${label}已按您的选择设为${value?'有':'没有'}。`;}catch{}}
async function saveCardText(code:string,themeId=activeTheme.value){
 const current=assignment(code);if(!current)return;const edit=cardEditForTheme(code,themeId);busy.value=true;
 try{await postVisitor('/place-themes',{place_code:code,expected_version:current.version,theme_ids:current.themeIds,family_friendly:current.familyFriendly,title_by_theme:{...current.titleByTheme,[themeId]:edit.title.trim()},summary_by_theme:{...current.summaryByTheme,[themeId]:edit.summary.trim()}});await load();message.value=`“${edit.title||placeName(code)}”在${themes.value.find(theme=>theme.id===themeId)?.name||themeId}中的卡片文字已更新。`;}
 catch(error){message.value=(error as Error).message;}finally{busy.value=false;}
}
async function saveContentPresentation(content:VContent,themeIds:string[],familyFriendly=content.draft.familyFriendly,text?:{title:string;summary:string}){
 busy.value=true;try{await postVisitor('/content-presentation',{content_id:content.id,expected_version:content.version,theme_ids:themeIds,family_friendly:familyFriendly,...(text?{title:text.title,summary:text.summary}:{})});await load();}catch(error){message.value=(error as Error).message;throw error;}finally{busy.value=false;}
}
async function addContent(content:VContent){try{await saveContentPresentation(content,[...new Set([...content.draft.themeIds,activeTheme.value])]);message.value=`已把“${content.draft.title}”加入${activeThemeData.value?.name||''}。`;}catch{}}
async function addContentToTheme(content:VContent,themeId:string){const theme=themes.value.find(item=>item.id===themeId);try{await saveContentPresentation(content,[...new Set([...content.draft.themeIds,themeId])]);message.value=`已把“${content.draft.title}”加入${theme?.name||themeId}。`;}catch{}}
async function removeContent(id?:string){const content=contents.value.find(item=>item.id===id);if(!content)return;try{await saveContentPresentation(content,content.draft.themeIds.filter(theme=>theme!==activeTheme.value));message.value=`已从${activeThemeData.value?.name||''}移除“${content.draft.title}”。`;}catch{}}
async function moveContent(id?:string){const content=contents.value.find(item=>item.id===id),target=id?moveTargets[`content:${id}`]:'';if(!content||!target)return;const theme=themes.value.find(item=>item.id===target);try{await saveContentPresentation(content,[...new Set([...content.draft.themeIds.filter(themeId=>themeId!==activeTheme.value),target])]);message.value=`已把“${content.draft.title}”移动至${theme?.name||target}。`;}catch{}}
async function toggleContentFamily(id?:string){const content=contents.value.find(item=>item.id===id);if(!content)return;try{await saveContentPresentation(content,content.draft.themeIds,!content.draft.familyFriendly);message.value=`“${content.draft.title}”已${content.draft.familyFriendly?'取消':'设为'}适合带孩子。`;}catch{}}
async function saveContentText(id?:string){const content=contents.value.find(item=>item.id===id);if(!content)return;const edit=contentEdit(content.id);try{await saveContentPresentation(content,content.draft.themeIds,content.draft.familyFriendly,edit);message.value=`“${edit.title}”卡片文字已更新。`;}catch{}}
async function assignUnassigned(item:Slot,themeId:string){if(item.placeCode)return addPlaceToTheme(item.placeCode,themeId);const content=contents.value.find(content=>content.id===item.contentId);if(content)return addContentToTheme(content,themeId);}
async function createCard(){
 if(!payload.value)return;busy.value=true;message.value='';
 try{const firstTheme=newCard.themeIds[0];const result=await postVisitor<any>('/quick-create',{expected_store_version:payload.value.state.version,title:newCard.title,summary:newCard.summary,place_code:newCard.placeCode,theme_ids:newCard.themeIds,family_friendly:newCard.familyFriendly,kind:newCard.kind});newCard.title='';newCard.summary='';newCard.placeCode='';newCard.themeIds=[];newCard.familyFriendly=false;newCard.kind='outdoor';showCreate.value=false;await load();if(firstTheme){activeTheme.value=firstTheme;section.value='themes';}message.value=`“${result.item.draft.title}”已新增并显示，现在可直接点击图片区域添加照片。`;}
 catch(error){message.value=(error as Error).message;}finally{busy.value=false;}
}
async function saveHomeText(){if(!payload.value)return;busy.value=true;try{const result=await postVisitor<any>('/home/text',{expected_version:payload.value.state.home.version,...homeText});payload.value.state.home=result.home;message.value='首页全部文字已更新。';}catch(error){message.value=(error as Error).message;}finally{busy.value=false;}}
function setHomeText(key:HomeTextKey,event:Event){homeText[key]=((event.currentTarget as HTMLElement).innerText||'').replace(/\r/g,'').trim();}
function recommendationKey(item:Slot,part:'title'|'summary'):HomeTextKey{
 if(item.slot===placeSlot('WY-0012'))return part==='title'?'recommendationMoonbayTitle':'recommendationMoonbaySummary';
 if(item.slot===placeSlot('WY-0024'))return part==='title'?'recommendationTaoyuanyuTitle':'recommendationTaoyuanyuSummary';
 return part==='title'?'recommendationManshuiTitle':'recommendationManshuiSummary';
}
async function saveThemeText(){if(!payload.value)return;const theme=themes.value.find(item=>item.id===activeTheme.value),edit=themeEdits[activeTheme.value];if(!theme||!edit)return;busy.value=true;try{await postVisitor('/theme-presentation',{theme_id:theme.id,expected_version:theme.version,...edit});await load();message.value=`“${edit.name}”主题文字已更新。`;}catch(error){message.value=(error as Error).message;}finally{busy.value=false;}}
function setThemeText(key:'name'|'icon'|'eyebrow'|'description',event:Event){const edit=themeEdits[activeTheme.value];if(edit)edit[key]=((event.currentTarget as HTMLElement).innerText||'').replace(/\r/g,'').trim();}
</script>

<template>
 <div class="workspace-page visual-maintenance">
  <div class="workspace-title simplified-title"><div><p class="kicker">像前台一样维护</p><h1>游客端维护</h1><p>点击图片直接更换；进入主题后可直接新增、移动卡片和修改前台文字。</p></div><div class="workspace-actions"><a class="button secondary" :href="visitorHomeUrl()" target="_blank">查看游客端</a><button class="secondary" @click="section='unassigned';showCreate=true">＋ 新增卡片</button></div></div>
  <SitePublish/>
  <p v-if="message" class="inline-message" role="status">{{message}}</p>
   <nav class="visual-section-tabs" aria-label="维护范围"><button :class="{active:section==='home'}" @click="section='home'">首页</button><button :class="{active:section==='themes'}" @click="section='themes'">主题卡片</button><button :class="{active:section==='unassigned'}" @click="section='unassigned'">未分类卡片</button><button :class="{active:section==='places'}" @click="section='places'">全部地点</button><button :class="{active:section==='route'}" @click="section='route'">一号风景道</button></nav>
   <div v-if="section==='themes'" class="visual-theme-tabs"><button v-for="theme in themes" :key="theme.id" :class="{active:activeTheme===theme.id}" @click="activeTheme=theme.id;showAdd=false"><span>{{theme.icon}}</span>{{theme.name}}</button></div>
  <div v-if="section==='themes'" class="theme-card-toolbar"><div><strong>{{activeThemeData?.name}}主题</strong><small>下方就是游客看到的卡片</small></div><button class="primary-action" @click="showAdd=!showAdd">{{showAdd?'收起':'＋ 添加卡片'}}</button></div>
  <section v-if="section==='themes'&&themeEdits[activeTheme]" class="theme-inline-editor" :style="image(`theme.${activeTheme}.hero`)?{backgroundImage:`linear-gradient(90deg,rgba(15,58,43,.88),rgba(15,58,43,.5)),url(${image(`theme.${activeTheme}.hero`)})`}:{}"><input :id="`theme-hero-${activeTheme}`" type="file" accept="image/*" :disabled="busy" @change="choose($event,themeSlots[0])"><label :for="`theme-hero-${activeTheme}`" class="theme-photo-hit"><i>{{image(`theme.${activeTheme}.hero`)?'更换主题头图':'添加主题头图'}}</i></label><div><small class="inline-editable" contenteditable="true" role="textbox" @keydown.enter.prevent @blur="setThemeText('eyebrow',$event)">{{themeEdits[activeTheme].eyebrow}}</small><div class="theme-inline-heading"><span class="inline-editable" contenteditable="true" role="textbox" @keydown.enter.prevent @blur="setThemeText('icon',$event)">{{themeEdits[activeTheme].icon}}</span><strong class="inline-editable" contenteditable="true" role="textbox" @keydown.enter.prevent @blur="setThemeText('name',$event)">{{themeEdits[activeTheme].name}}</strong></div><p class="inline-editable" contenteditable="true" role="textbox" @keydown.enter.prevent @blur="setThemeText('description',$event)">{{themeEdits[activeTheme].description}}</p><button :disabled="busy" @click="saveThemeText">保存主题页修改</button></div></section>
   <section v-if="section==='themes'&&showAdd" class="visual-add-panel">
   <div class="visual-add-heading"><div><h2>添加到“{{activeThemeData?.name}}”</h2><p>找到地点后点一次“加入”。</p></div><button class="secondary" @click="section='unassigned';showCreate=true">＋ 新增卡片</button></div>
   <label class="visual-search">搜索地点<input v-model="addQuery" type="search" placeholder="输入地点名称或 WY 编号"></label><label class="show-auxiliary"><input v-model="showAuxiliary" type="checkbox">显示停车场、卫生间等辅助点</label>
   <div class="visual-add-list"><article v-for="place in availablePlaces" :key="place.code"><span><strong>{{place.name}}</strong><small>{{place.code}}</small></span><button :disabled="busy" @click="addPlace(place.code)">加入</button></article></div>
   <details v-if="availableContents.length" class="available-content"><summary>添加已有自定义内容</summary><article v-for="content in availableContents" :key="content.id"><span><strong>{{content.draft.title}}</strong><small>{{content.draft.summary}}</small></span><button :disabled="busy" @click="addContent(content)">加入</button></article></details>
   </section>
  <section v-if="section==='unassigned'" class="unassigned-heading"><div><strong>未分类卡片</strong><small>这里只显示尚未加入任何主题的卡片，用来检查遗漏。</small></div><div class="unassigned-heading-actions"><label class="show-auxiliary"><input v-model="showAuxiliary" type="checkbox">显示停车场、卫生间等辅助点</label><button @click="showCreate=!showCreate">{{showCreate?'收起':'＋ 新增卡片'}}</button></div></section>
  <section v-if="section==='unassigned'&&showCreate" class="quick-card-create">
   <div class="quick-card-preview"><div class="quick-card-image"><span>点击创建后<br>即可添加图片</span></div><div><small>{{newCard.placeCode?placeName(newCard.placeCode):'沿路地点'}}</small><strong>{{newCard.title||'新卡片标题'}}</strong><p>{{newCard.summary||'用一句话告诉游客这里适合做什么。'}}</p><div class="visual-card-tags"><span v-for="themeId in newCard.themeIds" :key="themeId">{{themes.find(theme=>theme.id===themeId)?.name}}</span><span v-if="newCard.familyFriendly" class="family">适合带孩子</span></div></div></div>
   <div class="quick-card-form"><h2>直接新增前台卡片</h2><label>卡片标题<input v-model.trim="newCard.title" maxlength="160" placeholder="例如：星村补给休息"></label><label>卡片一句简介<textarea v-model.trim="newCard.summary" rows="3" maxlength="500" placeholder="例如：吃点东西，补充物资，顺路歇一会儿。"></textarea></label><label>卡片对应地点<select v-model="newCard.placeCode"><option value="">请选择地点</option><option v-for="place in validPlaces.filter(place=>place.place_type==='主地点')" :key="place.code" :value="place.code">{{place.name}}</option></select></label><fieldset><legend>加入哪些主题</legend><label v-for="theme in themes" :key="theme.id"><input v-model="newCard.themeIds" type="checkbox" :value="theme.id">{{theme.name}}</label></fieldset><label class="inline-check"><input v-model="newCard.familyFriendly" type="checkbox">适合带孩子</label><button :disabled="busy" @click="createCard">新增并显示这张卡片</button></div>
  </section>
  <label v-if="section==='places'||section==='unassigned'" class="visual-search">搜索地点<input v-model="query" type="search" placeholder="地点名称或 WY 编号"></label>
  <section v-if="section==='home'" class="inline-edit-help"><strong>直接点画面里的文字修改</strong><span>虚线框内都可以点；点图片可更换照片。</span></section>
  <section v-if="section==='home'" class="visual-front-preview"><div class="visual-front-title">武夷山奶爸地图 <span>•••</span></div><div class="visual-home-hero visual-home-edit" :style="image('home.hero')?{backgroundImage:`url(${image('home.hero')})`}:{}"><input id="home-hero-file" type="file" accept="image/*" :disabled="busy" @change="choose($event,homeSlots[0])"><span v-if="!image('home.hero')">等待真实素材</span><label for="home-hero-file" class="visual-home-photo-hit"><i>{{image('home.hero')?'点击更换首页主图':'点击添加首页主图'}}</i></label><div class="visual-home-copy"><small class="inline-editable" contenteditable="true" role="textbox" @keydown.enter.prevent @blur="setHomeText('eyebrow',$event)">{{homeText.eyebrow}}</small><strong><span class="inline-editable" contenteditable="true" role="textbox" @keydown.enter.prevent @blur="setHomeText('titleLine1',$event)">{{homeText.titleLine1}}</span><span class="inline-editable" contenteditable="true" role="textbox" @keydown.enter.prevent @blur="setHomeText('titleLine2',$event)">{{homeText.titleLine2}}</span></strong><p><span class="inline-editable" contenteditable="true" role="textbox" @keydown.enter.prevent @blur="setHomeText('introLine1',$event)">{{homeText.introLine1}}</span><span class="inline-editable" contenteditable="true" role="textbox" @keydown.enter.prevent @blur="setHomeText('introLine2',$event)">{{homeText.introLine2}}</span></p><div class="visual-home-actions"><b class="inline-editable" contenteditable="true" role="textbox" @keydown.enter.prevent @blur="setHomeText('mapButtonLabel',$event)">{{homeText.mapButtonLabel}}</b><b class="inline-editable" contenteditable="true" role="textbox" @keydown.enter.prevent @blur="setHomeText('corridorButtonLabel',$event)">{{homeText.corridorButtonLabel}}</b></div></div></div><div class="visual-admin-theme-grid"><article v-for="theme in themes" :key="theme.id"><span>{{theme.icon}}</span><strong>{{theme.name}}</strong><small class="inline-editable dark" contenteditable="true" role="textbox" @keydown.enter.prevent @blur="setHomeText('themeCardHint',$event)">{{homeText.themeCardHint}}</small></article></div><section class="visual-route-editor"><div class="visual-home-section-copy"><small class="inline-editable dark" contenteditable="true" role="textbox" @keydown.enter.prevent @blur="setHomeText('routesEyebrow',$event)">{{homeText.routesEyebrow}}</small><strong class="inline-editable dark" contenteditable="true" role="textbox" @keydown.enter.prevent @blur="setHomeText('routesTitle',$event)">{{homeText.routesTitle}}</strong></div><div class="visual-route-list"><article><b class="inline-editable dark" contenteditable="true" role="textbox" @keydown.enter.prevent @blur="setHomeText('routeFamilyTitle',$event)">{{homeText.routeFamilyTitle}}</b><small class="inline-editable dark" contenteditable="true" role="textbox" @keydown.enter.prevent @blur="setHomeText('routeFamilySummary',$event)">{{homeText.routeFamilySummary}}</small></article><article><b class="inline-editable dark" contenteditable="true" role="textbox" @keydown.enter.prevent @blur="setHomeText('routeDayTitle',$event)">{{homeText.routeDayTitle}}</b><small class="inline-editable dark" contenteditable="true" role="textbox" @keydown.enter.prevent @blur="setHomeText('routeDaySummary',$event)">{{homeText.routeDaySummary}}</small></article><article><b class="inline-editable dark" contenteditable="true" role="textbox" @keydown.enter.prevent @blur="setHomeText('routeTwoDayTitle',$event)">{{homeText.routeTwoDayTitle}}</b><small class="inline-editable dark" contenteditable="true" role="textbox" @keydown.enter.prevent @blur="setHomeText('routeTwoDaySummary',$event)">{{homeText.routeTwoDaySummary}}</small></article></div></section></section>
  <div class="visual-slot-grid" :class="{'single-hero':section==='route'}">
   <article v-for="item in visibleSlots" :key="item.slot" class="visual-slot-card" :class="{'is-main':item.slot.includes('.hero')}">
    <div v-if="supportsGallery(item)" class="visual-gallery-editor" :style="{aspectRatio:String(item.aspect)}"><div v-if="gallery(item.slot).length" class="visual-gallery-track"><figure v-for="(photo,index) in gallery(item.slot)" :key="photo.slot"><img :src="photo.url" :alt="`${item.title} ${index+1}`"><button type="button" :disabled="busy" @click="removeGalleryImage(item,photo.slot)">删除这张</button><span>{{index+1}} / {{gallery(item.slot).length}}</span></figure></div><label class="visual-gallery-add"><input type="file" accept="image/*" multiple :disabled="busy" @change="chooseGallery($event,item)"><b>＋</b>{{gallery(item.slot).length?'继续添加照片':'添加照片'}}<small>可一次选择多张</small></label></div>
    <label v-else class="visual-image-button" :style="{aspectRatio:String(item.aspect)}"><input type="file" accept="image/*" :disabled="busy" @change="choose($event,item)"><img v-if="image(item.slot)" :src="image(item.slot)" :alt="item.title"><span v-else><b>＋</b>点击添加图片</span><i>更换图片</i></label>
    <div class="visual-slot-copy"><div><template v-if="section==='home'"><strong class="inline-editable dark" contenteditable="true" role="textbox" @keydown.enter.prevent @blur="setHomeText(recommendationKey(item,'title'),$event)">{{item.title}}</strong><small class="inline-editable dark" contenteditable="true" role="textbox" @keydown.enter.prevent @blur="setHomeText(recommendationKey(item,'summary'),$event)">{{item.subtitle}}</small></template><template v-else-if="section==='themes'&&(item.placeCode||item.contentId)"><strong class="inline-editable dark" contenteditable="true" role="textbox" @keydown.enter.prevent @blur="setCardText(item,'title',$event)">{{item.placeCode?cardEdit(item.placeCode).title:contentEdit(item.contentId||'').title}}</strong><small class="inline-editable dark" contenteditable="true" role="textbox" @keydown.enter.prevent @blur="setCardText(item,'summary',$event)">{{item.placeCode?cardEdit(item.placeCode).summary:contentEdit(item.contentId||'').summary}}</small></template><template v-else><strong>{{item.title}}</strong><small>{{item.subtitle}}</small></template><div v-if="section==='themes'&&(item.placeCode||item.contentId)" class="visual-card-tags"><span>{{activeThemeData?.name}}</span><span v-if="item.familyFriendly" class="family">适合带孩子</span></div></div><button v-if="image(item.slot)" class="quiet" :disabled="busy" @click="removeImage(item)">移除图片</button></div>
    <div v-if="section==='themes'&&(item.placeCode||item.contentId)" class="visual-card-actions"><button class="primary-action" :disabled="busy" @click="item.placeCode?saveCardText(item.placeCode):saveContentText(item.contentId)">保存文字</button><button class="secondary" :disabled="busy" @click="item.placeCode?togglePlaceFamily(item.placeCode):toggleContentFamily(item.contentId)">{{item.familyFriendly?'取消带孩子':'适合带孩子'}}</button><RouterLink v-if="item.contentId" class="button secondary" :to="`/visitor-content/${item.contentId}`">编辑详情</RouterLink><button class="remove-button" :disabled="busy" @click="item.placeCode?removePlace(item.placeCode):removeContent(item.contentId)">从本主题移除</button></div>
    <div v-if="section==='themes'&&(item.placeCode||item.contentId)" class="move-theme"><label>移动至其他主题<select v-model="moveTargets[item.placeCode?`place:${item.placeCode}`:`content:${item.contentId}`]"><option value="">选择主题</option><option v-for="theme in themes.filter(theme=>theme.id!==activeTheme)" :key="theme.id" :value="theme.id">{{theme.name}}</option></select></label><button :disabled="busy||!moveTargets[item.placeCode?`place:${item.placeCode}`:`content:${item.contentId}`]" @click="item.placeCode?movePlace(item.placeCode):moveContent(item.contentId)">移动</button></div>
    <div v-if="section==='unassigned'&&(item.placeCode||item.contentId)" class="unassigned-theme-actions"><span>加入主题</span><button v-for="theme in themes" :key="theme.id" :disabled="busy" @click="assignUnassigned(item,theme.id)">{{theme.name}}</button></div>
    <div v-if="section!=='home'&&itemPlaceCode(item)" class="card-facility-editor"><button class="facility-disclosure" type="button" @click="expandedFacilities[item.slot]=!expandedFacilities[item.slot]"><span>本地点服务</span><b>{{facilityOptions.filter(entry=>facilityState(itemPlaceCode(item))[entry[0]]).length}} 项有</b><i>{{expandedFacilities[item.slot]?'收起':'设置'}} ↓</i></button><div v-if="expandedFacilities[item.slot]" class="facility-choice-list"><div v-for="entry in facilityOptions" :key="entry[0]"><strong>{{entry[1]}}</strong><button :class="{selected:facilityState(itemPlaceCode(item))[entry[0]]}" :disabled="busy" @click="setFacility(itemPlaceCode(item),entry[0],true)">✓ 有</button><button :class="{selected:!facilityState(itemPlaceCode(item))[entry[0]]}" :disabled="busy" @click="setFacility(itemPlaceCode(item),entry[0],false)">× 没有</button></div><p>以您在这里的选择为准，其他分类或旧记录不会覆盖。</p></div></div>
    <section v-if="section==='places'&&item.placeCode" class="all-place-maintenance"><div class="all-place-heading"><strong>这张地点卡出现在哪些主题</strong><small>点主题即可加入或移除</small></div><div class="all-place-theme-buttons"><button v-for="theme in themes" :key="theme.id" :class="{active:assignment(item.placeCode)?.themeIds.includes(theme.id)}" :disabled="busy" @click="togglePlaceTheme(item.placeCode,theme.id)"><span>{{theme.icon}}</span>{{theme.name}}</button></div><button class="family-toggle" :class="{active:assignment(item.placeCode)?.familyFriendly}" :disabled="busy" @click="togglePlaceFamily(item.placeCode)">{{assignment(item.placeCode)?.familyFriendly?'✓ 适合带孩子':'设为适合带孩子'}}</button><div class="all-place-card-previews"><article v-for="themeId in assignment(item.placeCode)?.themeIds||[]" :key="themeId" class="all-place-theme-copy" :class="themeId"><div class="front-card-theme"><span>{{themes.find(theme=>theme.id===themeId)?.icon}}</span>{{themes.find(theme=>theme.id===themeId)?.name}}</div><strong class="inline-editable dark" contenteditable="true" role="textbox" @keydown.enter.prevent @blur="setPlaceThemeText(item.placeCode,themeId,'title',$event)">{{cardEditForTheme(item.placeCode,themeId).title}}</strong><p class="inline-editable dark" contenteditable="true" role="textbox" @keydown.enter.prevent @blur="setPlaceThemeText(item.placeCode,themeId,'summary',$event)">{{cardEditForTheme(item.placeCode,themeId).summary||'点击这里填写一句简介'}}</p><div class="front-card-tags"><span>{{themes.find(theme=>theme.id===themeId)?.name}}</span><span v-if="assignment(item.placeCode)?.familyFriendly">适合带孩子</span></div><button :disabled="busy" @click="saveCardText(item.placeCode,themeId)">保存这张卡片</button></article></div></section>
   </article>
  </div>
  <section v-if="section==='home'" class="home-inline-save"><p>画面中的文字修改后，统一保存一次。</p><button :disabled="busy" @click="saveHomeText">保存首页修改</button></section>
  <p v-if="section!=='home'&&!visibleSlots.length" class="empty-state">{{section==='unassigned'?'没有遗漏：所有卡片都已经加入至少一个主题。':'这里暂时没有卡片。点击上方“添加卡片”即可加入。'}}</p>
  <ImageCropDialog v-if="crop" :file="crop.file" :title="crop.item.title" :aspect="crop.item.aspect" @cancel="crop=null;cropQueue=[]" @confirm="applyCrop"/>
 </div>
</template>
